-- ===========================================================================
-- DYNAMIC SEED DATA: ACCOMMODATION COMPLIANCE MODULE
-- TENANT RESOLVED DYNAMICALLY FROM: KREUP_AI
-- DATE RANGE: Previous Month (June 2026), Current Month (July 2026), Next Month (August 2026)
-- ===========================================================================

BEGIN;

SET search_path TO auraos, public;

-- 1. RESOLVE DYNAMIC VARIABLES (TENANT & COMPANY & AUDIT USER)
CREATE TEMP TABLE vars AS
SELECT 
  COALESCE((SELECT id FROM aura_tenant WHERE code = 'KREUP_AI' LIMIT 1), 'ae63d8ef-d01d-49a7-a542-b1256702765d') AS tenant_id,
  COALESCE((SELECT id FROM aura_user WHERE email LIKE '%kreup%' LIMIT 1), 'system_manager') AS user_id;

-- 2. CREATE DYNAMIC EMPLOYEE LOOKUP TABLE
CREATE TEMP TABLE temp_employees AS
SELECT ROW_NUMBER() OVER (ORDER BY e.id) AS row_num, e.id
FROM aura_employee e
JOIN aura_company c ON e."companyId" = c.id
WHERE c."tenantId" = (SELECT tenant_id FROM vars) AND e."isDeleted" = false;

-- 3. CLEANUP PREVIOUS DATA FOR TENANT
DELETE FROM aura_accommodation_certificate WHERE "tenantId" = (SELECT tenant_id FROM vars);
DELETE FROM aura_accommodation_complaint WHERE "tenantId" = (SELECT tenant_id FROM vars);
DELETE FROM aura_accommodation_inspection WHERE "tenantId" = (SELECT tenant_id FROM vars);
DELETE FROM aura_accommodation_assignment WHERE "tenantId" = (SELECT tenant_id FROM vars);
DELETE FROM aura_accommodation_site WHERE "tenantId" = (SELECT tenant_id FROM vars);

