-- ===========================================================================
-- 9. VERIFICATION QUERIES
-- ===========================================================================
SELECT 'Sites count verified' AS check_name, COUNT(*) = 40 AS passed FROM aura_accommodation_site WHERE "tenantId" = (SELECT tenant_id FROM vars);
SELECT 'Assignments count verified' AS check_name, COUNT(*) = 350 AS passed FROM aura_accommodation_assignment WHERE "tenantId" = (SELECT tenant_id FROM vars);
SELECT 'Inspections count verified' AS check_name, COUNT(*) = 220 AS passed FROM aura_accommodation_inspection WHERE "tenantId" = (SELECT tenant_id FROM vars);
SELECT 'Complaints count verified' AS check_name, COUNT(*) = 240 AS passed FROM aura_accommodation_complaint WHERE "tenantId" = (SELECT tenant_id FROM vars);
SELECT 'Overcapacity sites exist (> 0)' AS check_name, COUNT(*) > 0 AS passed FROM aura_accommodation_site WHERE "currentOccupancy" > "totalCapacity" AND "tenantId" = (SELECT tenant_id FROM vars);
SELECT 'SLA breached complaints exist' AS check_name, COUNT(*) > 0 AS passed FROM aura_accommodation_complaint WHERE status = 'OPEN' AND "raisedAt" < NOW() - INTERVAL '48 hours' AND "tenantId" = (SELECT tenant_id FROM vars);
SELECT 'Gated certificates exist' AS check_name, COUNT(*) > 0 AS passed FROM aura_accommodation_certificate WHERE "gatingReason" IS NOT NULL AND "tenantId" = (SELECT tenant_id FROM vars);

DROP TABLE temp_employees;
DROP TABLE vars;
